1	import Stripe from "stripe";
2	import type { Prisma } from "@prisma/client";
3	import { db } from "./db";
4	import type { OrderIntent, OrderPrice } from "./order";
5	import { orderPriceOf, orderQuote, parseOrderPrice } from "./order";
6	import { sanitizeCampaign } from "./promo-redemption";
7	import { invoiceCreateData } from "./invoices";
8	
9	export function stripeConfigured(): boolean {
10	  return !!process.env.STRIPE_SECRET_KEY;
11	}
12	
13	let client: Stripe | null = null;
14	
15	export function stripe(): Stripe {
16	  if (!process.env.STRIPE_SECRET_KEY) throw new Error("Stripe is not configured");
17	  if (!client) client = new Stripe(process.env.STRIPE_SECRET_KEY);
18	  return client;
19	}
20	
21	/** Stripe's hard limit on a single metadata VALUE. */
22	export const STRIPE_METADATA_VALUE_MAX = 500;
23	
24	/**
25	 * How long an order Checkout session stays payable. Kept SHORT (1h) on purpose: the
26	 * managed first-month-free hold (lib/promo-redemption.ts reserveFirstMonthFree) lives
27	 * exactly as long as the session can still be paid, so a shorter session means a
28	 * customer who abandons checkout gets their one-time offer back sooner. Stripe's
29	 * accepted range is 30 min – 24 h; 1 h sits comfortably inside it.
30	 */
31	export const ORDER_CHECKOUT_EXPIRES_MS = 60 * 60 * 1000;
32	
33	/**
34	 * Serialise a payload for Stripe metadata, refusing rather than truncating.
35	 *
36	 * WHY THIS EXISTS. Every one of these payloads used to be written as
37	 * `JSON.stringify(x).slice(0, 490)`. A slice through JSON produces a string that
38	 * is no longer JSON, and the consumer's `JSON.parse` throws inside a `try` that
39	 * returns `null` on failure — at which point `fulfilCheckoutSession` cannot see an
40	 * order, a resize or a disk expansion in the session, and falls through to its
41	 * plain wallet-top-up branch. The customer's card is charged, the money lands in
42	 * their wallet, **no server is created, no error is shown and no failure row is
43	 * written**. Silent, and invisible from every surface we own.
44	 *
45	 * The correct behaviour was already argued for elsewhere in this file, about the
46	 * card leg: "Refuse to open a session rather than take the money and discover it
47	 * at confirm time — nothing has been charged at this point." That reasoning
48	 * applies identically here, so it is applied identically. Throwing happens BEFORE
49	 * `checkout.sessions.create`, so the customer sees a failure on a page where they
50	 * have paid nothing, which is the cheapest possible moment to fail.
51	 *
52	 * Never re-introduce a slice here. If a payload legitimately outgrows the cap, the
53	 * fix is to persist it and put a key in metadata — never to send half of it.
54	 */
55	export function packMetadata(label: string, payload: unknown): string {
56	  const json = JSON.stringify(payload);
57	  if (json.length > STRIPE_METADATA_VALUE_MAX) {
58	    throw new Error(
59	      `${label} is ${json.length} characters, over Stripe's ${STRIPE_METADATA_VALUE_MAX}-character metadata limit. ` +
60	        `Refusing to create a payment session rather than send a truncated payload that would take the money and ` +
61	        `provision nothing.`,
62	    );
63	  }
64	  return json;
65	}
66	
67	/**
68	 * Create a Checkout session that pays for a VPS order directly (no wallet pre-fund).
69	 *
70	 * `amountCents` is the CARD leg only (the remainder after wallet credit); the FULL
71	 * order total rides along in metadata as `nxeonOrderPrice` so the confirm route can
72	 * settle the price this order was SOLD at instead of re-pricing it once the card
73	 * has already cleared. That re-pricing — and the silent wallet draw that paid for
74	 * it — is the H2 incident described on `OrderPrice` in lib/order.ts.
75	 *
76	 * `sold` lets the caller hand in the very quote it split the payment from, so the
77	 * card leg and the stamped total are two halves of ONE pricing. When it is omitted
78	 * the order is priced here, once, at the moment the session is created — still
79	 * before any money moves, which is the property that matters.
80	 */
81	export async function createOrderCheckout(
82	  user: { id: string; email: string },
83	  amountCents: number,
84	  intent: OrderIntent,
85	  sold?: OrderPrice | null,
86	  campaign?: string,
87	  /**
88	   * The managed first-month-free HOLD token, when this order was sold WITH the free
89	   * month. Reserved by `reserveFirstMonthFree` BEFORE this session is created, so the
90	   * discounted price stamped here is already backed by an exclusive hold. It rides in
91	   * metadata so fulfilment can CONFIRM the hold (never a fresh, contended claim) and
92	   * the `checkout.session.expired` webhook can RELEASE it. Null/omitted for a
93	   * full-price order (nothing to confirm).
94	   */
95	  promoReservationToken?: string | null,
96	  /**
97	   * The checkout-coupon HOLD token, when this order was sold WITH a coupon discount.
98	   * Reserved by `reserveOrderCoupon` (lib/coupon-redemption.ts) BEFORE this session is
99	   * created, so the discounted price stamped here is already backed by an exclusive hold
100	   * (per-person + a global-cap slot). It rides in metadata so fulfilment can CONFIRM the
101	   * hold (never a fresh, contended claim) and the `checkout.session.expired` webhook can
102	   * RELEASE it. Null/omitted for a full-price order.
103	   */
104	  couponReservationToken?: string | null,
105	): Promise<string | null> {
106	  if (!stripeConfigured() || amountCents <= 0) return null;
107	  const base = process.env.APP_URL ?? "http://localhost:3000";
108	  const price = sold ?? orderPriceOf(await orderQuote(intent));
109	  // The card leg is a PART of the total; a card charge larger than the whole order
110	  // means the two were priced against different worlds and the wallet would have to
111	  // absorb a negative. Refuse to open a session rather than take the money and
112	  // discover it at confirm time — nothing has been charged at this point.
113	  if (price.chargeCents < amountCents) {
114	    throw new Error(
115	      `Order checkout: card leg ${amountCents}c exceeds the order total ${price.chargeCents}c`,
116	    );
117	  }
118	  // SSH keys are long; keep them out of Stripe metadata (500-char cap) — addable after deploy.
119	  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
120	  const session = await stripe().checkout.sessions.create({
121	    mode: "payment",
122	    customer_email: user.email,
123	    // Bound the session's payable life so an abandoned checkout returns the customer's
124	    // first-month-free hold quickly (the hold's reservedUntil is pinned just past this).
125	    expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
126	    line_items: [
127	      {
128	        price_data: {
129	          currency: "usd",
130	          product_data: { name: `Nxeon VPS — ${intent.hostname}` },
131	          unit_amount: amountCents,
132	        },
133	        quantity: 1,
134	      },
135	    ],
136	    metadata: {
137	      nxeonUserId: user.id,
138	      nxeonOrder: packMetadata("Order intent", slim),
139	      // Its OWN key, not a field inside `nxeonOrder`, so the two are independently
140	      // sized and a long intent can never displace the price.
141	      nxeonOrderPrice: packMetadata("Order price", price),
142	      // First-month-free ad campaign tag (from the /go link cookie), carried through
143	      // the card round-trip so the redemption records attribution at fulfil time —
144	      // the webhook has no request cookies to read it from.
145	      nxeonPromoCampaign: sanitizeCampaign(campaign),
146	      // The first-month-free HOLD token. Present only when the discounted price above
147	      // is backed by a reserved hold; fulfilment confirms it, expiry releases it.
148	      ...(promoReservationToken ? { nxeonPromoReservation: promoReservationToken } : {}),
149	      // The checkout-coupon HOLD token — same lifecycle as the promo one above, for the
150	      // coupon's per-person + global-cap slot. Present only on a coupon-discounted order.
151	      ...(couponReservationToken ? { nxeonCouponReservation: couponReservationToken } : {}),
152	    },
153	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
154	    cancel_url: `${base}/dashboard/deploy?canceled=1`,
155	  });
156	  return session.url;
157	}
158	
159	/**
160	 * Create a Checkout session that pays for a prorated server UPGRADE directly (no
161	 * wallet pre-fund), applying the customer's wallet balance to the split. The CARD
162	 * is charged only `cardCents` (the remainder after wallet credit); the FULL
163	 * proration is recorded in metadata as `chargeCents` so the confirm route debits
164	 * the whole proration back out of the wallet. Since creditCheckoutSession credited
165	 * only the card portion, the wallet naturally absorbs the difference — the wallet
166	 * is never touched before the card clears.
167	 */
168	export async function createResizeCheckout(
169	  user: { id: string; email: string },
170	  cardCents: number,
171	  resize: { serverId: string; planId: string; planName?: string; prorateCents: number },
172	): Promise<string | null> {
173	  if (!stripeConfigured() || cardCents <= 0) return null;
174	  const base = process.env.APP_URL ?? "http://localhost:3000";
175	  const session = await stripe().checkout.sessions.create({
176	    mode: "payment",
177	    customer_email: user.email,
178	    line_items: [
179	      {
180	        price_data: {
181	          currency: "usd",
182	          product_data: { name: `Nxeon VPS upgrade${resize.planName ? ` — ${resize.planName}` : ""}` },
183	          unit_amount: cardCents,
184	        },
185	        quantity: 1,
186	      },
187	    ],
188	    metadata: {
189	      nxeonUserId: user.id,
190	      // chargeCents = the FULL proration to debit on confirm (not the card amount).
191	      nxeonResize: packMetadata("Resize intent", {
192	        serverId: resize.serverId,
193	        planId: resize.planId,
194	        chargeCents: resize.prorateCents,
195	      }),
196	    },
197	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
198	    cancel_url: `${base}/dashboard/servers/${resize.serverId}?canceled=1`,
199	  });
200	  return session.url;
201	}
202	
203	/**
204	 * Create a Checkout session that pays for a prorated per-server DISK EXPANSION
205	 * directly (no wallet pre-fund), applying the customer's wallet balance to the
206	 * split. Structurally identical to createResizeCheckout: the CARD is charged only
207	 * `cardCents` (the remainder after wallet credit) while the FULL proration travels
208	 * in metadata as `chargeCents`, so the confirm route debits the whole proration
209	 * back out of the wallet against the just-credited card amount. The wallet is
210	 * never touched before the card clears.
211	 */
212	export async function createDiskExpandCheckout(
213	  user: { id: string; email: string },
214	  cardCents: number,
215	  expand: { serverId: string; addGB: number; hostname?: string; prorateCents: number },
216	): Promise<string | null> {
217	  if (!stripeConfigured() || cardCents <= 0) return null;
218	  const base = process.env.APP_URL ?? "http://localhost:3000";
219	  const session = await stripe().checkout.sessions.create({
220	    mode: "payment",
221	    customer_email: user.email,
222	    line_items: [
223	      {
224	        price_data: {
225	          currency: "usd",
226	          product_data: {
227	            name: `Nxeon +${expand.addGB} GB disk${expand.hostname ? ` — ${expand.hostname}` : ""}`,
228	            // The one-way nature is on the Stripe page itself, not just in our UI.
229	            description: "Permanent storage expansion — disk space can be added but never removed.",
230	          },
231	          unit_amount: cardCents,
232	        },
233	        quantity: 1,
234	      },
235	    ],
236	    metadata: {
237	      nxeonUserId: user.id,
238	      // chargeCents = the FULL proration to debit on confirm (not the card amount).
239	      nxeonDiskExpand: packMetadata("Disk expansion intent", {
240	        serverId: expand.serverId,
241	        addGB: expand.addGB,
242	        chargeCents: expand.prorateCents,
243	      }),
244	    },
245	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
246	    cancel_url: `${base}/dashboard/servers/${expand.serverId}?canceled=1`,
247	  });
248	  return session.url;
249	}
250	
251	/**
252	 * A cents amount that arrived from OUTSIDE this process (Stripe metadata) and is
253	 * about to be handed to `debitWallet`. Integer, non-negative, finite — anything
254	 * else is refused rather than coerced, for the same reason `parseOrderPrice`
255	 * refuses a half-valid price: the caller's `?? quote.prorateCents` fallback would
256	 * silently RE-PRICE the purchase at confirm time, which is the H2 incident.
257	 */
258	function parseChargeCents(raw: unknown): number | null {
259	  if (typeof raw !== "number" || !Number.isInteger(raw) || raw < 0) return null;
260	  return raw;
261	}
262	
263	function parseId(raw: unknown): string | null {
264	  return typeof raw === "string" && raw.length > 0 ? raw : null;
265	}
266	
267	/**
268	 * WHAT a paid Checkout session was for — the ONE decision that routes fulfilment.
269	 *
270	 * REAL DEFECT this shape exists to remove (found 2026-07-27 audit). Fulfilment used
271	 * to ask three separate `getCheckout*Intent` helpers, each of which did its OWN
272	 * `sessions.retrieve` inside a `try` that returned `null` on ANY failure. So a
273	 * transient Stripe error — a 5xx, a rate limit, a dropped socket — turned "I could
274	 * not read this session" into "this session has no purchase metadata", and
275	 * `fulfilCheckoutSession` fell through to its plain wallet-top-up branch reporting
276	 * `fulfilled: true`. Card charged, no server, no `FulfilledSession` row, no
277	 * notification, and the webhook returns 200 so Stripe never retries. Exactly the
278	 * class of invisible failure that file was written to end, one layer up.
279	 *
280	 * `unreadable` and `unpaid` are therefore first-class answers, NOT absences. The
281	 * session is retrieved exactly once (`getCheckoutPurpose`, which THROWS rather than
282	 * returning a lie) and classified by a pure function over its metadata.
283	 */
284	export type CheckoutPurpose =
285	  | {
286	      kind: "order";
287	      userId: string;
288	      intent: OrderIntent;
289	      sold: OrderPrice | null;
290	      campaign: string;
291	      /** The first-month-free hold to confirm at fulfilment; null for a full-price order. */
292	      promoReservationToken: string | null;
293	      /** The checkout-coupon hold to confirm at fulfilment; null for a full-price order. */
294	      couponReservationToken: string | null;
295	    }
296	  | { kind: "resize"; userId: string; serverId: string; planId: string; chargeCents: number }
297	  | { kind: "diskExpand"; userId: string; serverId: string; addGB: number; chargeCents: number }
298	  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */
299	  | { kind: "topup"; userId: string | null }
300	  /** Not paid (or paid to nobody) — nothing to fulfil and nothing to claim. */
301	  | { kind: "unpaid" }
302	  /** Purchase metadata IS present but cannot be trusted. Never treat as a top-up. */
303	  | { kind: "unreadable"; userId: string | null; detail: string };
304	
305	/**
306	 * Classify a retrieved session. Pure — no clock, no network, no database — so the
307	 * routing decision is unit-testable and identical for the redirect and the webhook.
308	 */
309	export function classifyCheckoutSession(
310	  session: Pick<Stripe.Checkout.Session, "metadata" | "payment_status">,
311	): CheckoutPurpose {
312	  const md = session.metadata ?? null;
313	  const userId = parseId(md?.nxeonUserId);
314	  if (!userId || session.payment_status !== "paid") return { kind: "unpaid" };
315	
316	  const orderRaw = md?.nxeonOrder;
317	  if (orderRaw) {
318	    let intent: unknown;
319	    try {
320	      intent = JSON.parse(orderRaw);
321	    } catch {
322	      return { kind: "unreadable", userId, detail: "nxeonOrder is not valid JSON" };
323	    }
324	    if (!intent || typeof intent !== "object") {
325	      return { kind: "unreadable", userId, detail: "nxeonOrder is not an object" };
326	    }
327	    return {
328	      kind: "order",
329	      userId,
330	      intent: intent as OrderIntent,
331	      sold: parseOrderPrice(session.metadata?.nxeonOrderPrice),
332	      campaign: sanitizeCampaign(md?.nxeonPromoCampaign),
333	      promoReservationToken: parseId(md?.nxeonPromoReservation),
334	      couponReservationToken: parseId(md?.nxeonCouponReservation),
335	    };
336	  }
337	
338	  const resizeRaw = md?.nxeonResize;
339	  if (resizeRaw) {
340	    let p: Record<string, unknown>;
341	    try {
342	      p = JSON.parse(resizeRaw) as Record<string, unknown>;
343	    } catch {
344	      return { kind: "unreadable", userId, detail: "nxeonResize is not valid JSON" };
345	    }
346	    const serverId = parseId(p?.serverId);
347	    const planId = parseId(p?.planId);
348	    const chargeCents = parseChargeCents(p?.chargeCents);
349	    if (!serverId || !planId || chargeCents === null) {
350	      return { kind: "unreadable", userId, detail: "nxeonResize is missing serverId/planId/chargeCents" };
351	    }
352	    return { kind: "resize", userId, serverId, planId, chargeCents };
353	  }
354	
355	  const expandRaw = md?.nxeonDiskExpand;
356	  if (expandRaw) {
357	    let p: Record<string, unknown>;
358	    try {
359	      p = JSON.parse(expandRaw) as Record<string, unknown>;
360	    } catch {
361	      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is not valid JSON" };
362	    }
363	    const serverId = parseId(p?.serverId);
364	    const addGB = parseChargeCents(p?.addGB);
365	    const chargeCents = parseChargeCents(p?.chargeCents);
366	    if (!serverId || addGB === null || chargeCents === null) {
367	      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is missing serverId/addGB/chargeCents" };
368	    }
369	    return { kind: "diskExpand", userId, serverId, addGB, chargeCents };
370	  }
371	
372	  return { kind: "topup", userId };
373	}
374	
375	/**
376	 * Retrieve a Checkout session ONCE. Throws when Stripe cannot be read — the caller
377	 * must never be able to mistake a transport failure for "this session is a top-up".
378	 */
379	export async function retrieveCheckoutSession(sessionId: string): Promise<Stripe.Checkout.Session> {
380	  if (!stripeConfigured()) throw new Error("Stripe is not configured");
381	  return stripe().checkout.sessions.retrieve(sessionId);
382	}
383	
384	/** Retrieve + classify in one step. Throws on a Stripe read failure, never lies. */
385	export async function getCheckoutPurpose(sessionId: string): Promise<CheckoutPurpose> {
386	  return classifyCheckoutSession(await retrieveCheckoutSession(sessionId));
387	}
388	
389	/**
390	 * True when this session's card payment is the FUNDING LEG of a purchase — a VPS
391	 * order, an upgrade, a disk expansion — rather than a wallet top-up the customer
392	 * bought for its own sake.
393	 *
394	 * The wallet is the settlement bus for every card-paid purchase: the card amount
395	 * is credited in, then the purchase debits the full total back out. That credit is
396	 * plumbing, not a product, and it must not be documented as one.
397	 *
398	 * REAL INCIDENT (2026-07-26 rehearsal, H3): every paid session got a PAID "Wallet
399	 * top-up" invoice here AND a PAID invoice from whatever it funded, so one $82.53
400	 * annual purchase produced `Wallet top-up $82.53` + `Starter VPS — Annual $82.53`
401	 * and the invoices page reported $165.06 paid lifetime — a customer reconciling
402	 * against their card statement saw twice their spend. Each document was internally
403	 * consistent; there were simply two of them for one payment. worker/billing.ts
404	 * already states the rule for the renewal path: "No invoice for the card leg …
405	 * a second document for the card portion would double-count the same revenue."
406	 *
407	 * Reads the same three metadata keys `lib/fulfil-checkout.ts` dispatches on, so
408	 * "did this session fund a purchase" has one answer, not two.
409	 */
410	export function isPurchaseLegSession(metadata: Stripe.Metadata | null | undefined): boolean {
411	  return !!(metadata?.nxeonOrder || metadata?.nxeonResize || metadata?.nxeonDiskExpand);
412	}
413	
414	/**
415	 * Credit a user's wallet for a completed Checkout session, idempotently.
416	 * Called from both the success-redirect confirm route (works without HTTPS)
417	 * and the webhook (belt-and-suspenders once HTTPS is available).
418	 * Returns true if a credit was applied this call.
419	 *
420	 * Takes the ALREADY-RETRIEVED session rather than an id: `fulfilCheckoutSession`
421	 * fetches it once and both the credit and the fulfilment routing read that single
422	 * object, so the two can never disagree about what this payment was (and a Stripe
423	 * read failure surfaces in one place, loudly, instead of four times as `null`).
424	 */
425	export async function creditCheckoutSession(session: Stripe.Checkout.Session): Promise<boolean> {
426	  const userId = session.metadata?.nxeonUserId;
427	  const cents = session.amount_total ?? 0;
428	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
429	
430	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
431	  // session id inside the description.
432	  const legacy = await db.walletTransaction.findFirst({
433	    where: { stripeSessionId: null, description: { contains: session.id } },
434	  });
435	  if (legacy) return false;
436	
437	  // Is this credit a product the customer bought, or the funding leg of something
438	  // else they bought? Only the first is a "Wallet top-up" and only the first gets
439	  // a billing document — see isPurchaseLegSession for the incident.
440	  const purchaseLeg = isPurchaseLegSession(session.metadata);
441	
442	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
443	  // read-then-write check. The confirm-redirect and the webhook can arrive
444	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
445	  // only the database can safely decide the winner. P2002 == already credited.
446	  const ops: Prisma.PrismaPromise<unknown>[] = [
447	    db.walletTransaction.create({
448	      data: {
449	        userId,
450	        amountCents: cents,
451	        description: `Stripe payment (${session.id})`,
452	        stripeSessionId: session.id,
453	      },
454	    }),
455	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
456	    db.notification.create({
457	      data: {
458	        userId,
459	        title: `Payment of $${(cents / 100).toFixed(2)} received`,
460	        href: "/dashboard/billing",
461	      },
462	    }),
463	  ];
464	  // Index of the invoice-create inside `ops`, or -1 when no invoice is issued
465	  // (a purchase leg). Used to recover the new invoice's id for the receipt email.
466	  let invoiceOpIndex = -1;
467	  if (!purchaseLeg) {
468	    // PAID invoice for the top-up. Created in the SAME guarded transaction as
469	    // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
470	    // the credit idempotent also prevents a duplicate invoice on replay.
471	    //
472	    // A purchase leg is deliberately left undocumented HERE: the order, resize or
473	    // disk-expansion it funds issues the one invoice for the whole purchase, and
474	    // that document — not this one — is what the customer's card statement shows.
475	    // If the fulfilment then fails the money stays in the wallet as an ordinary
476	    // credit (ledger row + notification), and the invoice is issued by whatever it
477	    // is eventually spent on; inventing a top-up document at that point would
478	    // double-count the same dollars all over again the moment they deploy.
479	    // Remember WHERE in the batch this lands, so the created row's id can be read
480	    // back out of the transaction result. The receipt email promises the customer
481	    // an attached invoice, and it can only keep that promise if it knows the id.
482	    invoiceOpIndex = ops.length;
483	    ops.push(
484	      db.invoice.create({
485	        data: invoiceCreateData({
486	          userId,
487	          description: "Wallet top-up",
488	          status: "PAID",
489	          lineItems: [
490	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
491	          ],
492	        }),
493	      }),
494	    );
495	  }
496	  let invoiceId: string | undefined;
497	  try {
498	    const results = await db.$transaction(ops);
499	    if (invoiceOpIndex >= 0) {
500	      const created = results[invoiceOpIndex] as { id?: string } | undefined;
501	      invoiceId = created?.id;
502	    }
503	  } catch (e) {
504	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
505	    throw e;
506	  }
507	  // A funded wallet is the referred user's first paid action — reward both sides.
508	  try {
509	    const { maybeRewardReferral } = await import("./actions-growth");
510	    await maybeRewardReferral(userId);
511	  } catch { /* best-effort */ }
512	  try {
513	    const u = await db.user.findUnique({ where: { id: userId } });
514	    if (u) {
515	      const { sendMail, emails } = await import("./mailer");
516	      // Say what the money was for. On a purchase leg it is emphatically NOT a
517	      // top-up, and a receipt that calls it one is the same false statement the
518	      // duplicate invoice used to make, just in the customer's inbox.
519	      // The third argument is the promise, and it is the truth: we claim an attached
520	      // invoice only when there is an invoice id to attach. A purchase leg issues no
521	      // top-up invoice (the order does), so its receipt points at billing history
522	      // instead of promising a file that was never generated.
523	      const tpl = emails.receipt(
524	        `$${(cents / 100).toFixed(2)}`,
525	        purchaseLeg ? "your Nxeon order" : "wallet top-up",
526	        !!invoiceId,
527	      );
528	      // `kind` + `userId` hands this to the preference policy in lib/prefs.ts.
529	      // A receipt is ACCOUNT tier — suppressible by email if the customer turned
530	      // account email off. This is the one send site where that toggle actually
531	      // bites today, so it is the one that made the switch a lie.
532	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html, userId, kind: "receipt", invoiceId });
533	    }
534	  } catch { /* best-effort */ }
535	  return true;
536	}
