164	/**
165	 * Build the `data` payload for an Invoice row WITHOUT touching the database, so
166	 * a charge site can create the invoice inside its own guarded `$transaction`
167	 * (sharing the charge's idempotency guard) via `tx.invoice.create({ data })`.
168	 * The stored total (`amountCents`) is always derived from line items + tax so
169	 * callers can't desync the stamped total from the itemised breakdown.
170	 */
171	export function invoiceCreateData(opts: InvoiceInput): Prisma.InvoiceUncheckedCreateInput {
172	  const items = opts.lineItems.map((li) => ({
173	    description: String(li.description),
174	    qty: Number(li.qty) || 0,
175	    unitCents: Math.round(Number(li.unitCents) || 0),
176	    amountCents: Math.round(
177	      Number(li.amountCents ?? (Number(li.qty) || 0) * (Number(li.unitCents) || 0)) || 0
178	    ),
179	  }));
180	  const taxCents = Math.round(opts.taxCents ?? 0);
181	  const subtotalCents = items.reduce((s, li) => s + li.amountCents, 0);
182	  const amountCents = subtotalCents + taxCents;
183	  const status = opts.status ?? "OPEN";
184	
185	  return {
186	    userId: opts.userId,
187	    description: opts.description,
188	    lineItems: items,
189	    taxCents,
190	    amountCents,
191	    status,
192	    paidAt: status === "PAID" ? new Date() : null,
193	    // Only stamp the paying card on invoices born PAID; an OPEN invoice has not
194	    // been charged to any card yet.
195	    paidBrand: status === "PAID" ? opts.paidBrand ?? null : null,
196	    paidLast4: status === "PAID" ? opts.paidLast4 ?? null : null,
197	    periodStart: opts.period?.start ?? null,
198	    periodEnd: opts.period?.end ?? null,
199	  };
200	}
