1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireUser, assertNotImpersonating } from "./auth";
6	// Re-exporting a const from a "use server" file is illegal (Next throws
7	// "found object"), so the choices live in a plain module.
8	import { BACKUP_INTERVAL_CHOICES } from "./backup-intervals";
9	import { prorateDowngradeCreditCents, remainingMonths } from "./proration";
10	import { annualDiscountPct, frozenAnnualDiscountPct } from "./annual-discount";
11	
12	/**
13	 * Server lifecycle "extras" — scheduled backups, reinstall-to-a-different-OS and
14	 * resize-down. These complement the primary flows in `lib/actions-server.ts`
15	 * (create backup, resize-up, reinstall-same-OS). Every op is ownership-checked
16	 * and respects the "one in-flight job per server" invariant.
17	 */
18	
19	async function ownedServer(serverId: string) {
20	  const user = await requireUser();
21	  const server = await db.server.findUnique({
22	    where: { id: serverId },
23	    include: { plan: true, osTemplate: true },
24	  });
25	  if (!server) throw new Error("Not found");
26	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
27	  return { user, server };
28	}
29	
30	async function hasInflightJob(serverId: string): Promise<boolean> {
31	  const pending = await db.job.count({
32	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
33	  });
34	  return pending > 0;
35	}
36	
37	// ---------- 1. Scheduled backups ----------
38	
39	/**
40	 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
41	 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
42	 * first backup on its next pass.
43	 */
44	export async function setBackupSchedule(
45	  serverId: string,
46	  enabled: boolean,
47	  intervalHours: number
48	): Promise<{ error?: string }> {
49	  const { user, server } = await ownedServer(serverId);
50	
51	  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
52	    return { error: "Choose a valid backup interval." };
53	  }
54	
55	  await db.server.update({
56	    where: { id: server.id },
57	    data: {
58	      autoBackup: enabled,
59	      backupIntervalHours: enabled ? intervalHours : null,
60	    },
61	  });
62	  await db.auditLog.create({
63	    data: {
64	      userId: user.id,
65	      action: "server.backup_schedule",
66	      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
67	    },
68	  });
69	  revalidatePath(`/dashboard/servers/${serverId}`);
70	  return {};
71	}
72	
73	// ---------- 1b. Retry a failed provision ----------
74	
75	/**
76	 * Re-enqueue provisioning for a server that failed to build (status ERROR).
77	 *
78	 * A terminal PROVISION failure strands the server in ERROR with a red banner and
79	 * no way forward; this is the customer's self-service retry. It re-uses the exact
80	 * same job/worker machinery as the original order — the provision handler keeps
81	 * any vmid already persisted on the row, so a retry resumes rather than leaking a
82	 * second VM. Ownership-checked, guarded to ERROR only, and respects the one
83	 * in-flight job invariant. Moving the row to PROVISIONING immediately makes the
84	 * detail page show the transitional "being set up" state (and auto-refresh)
85	 * rather than the stale ERROR banner while the worker picks the job up.
86	 */
87	export async function retryProvision(serverId: string): Promise<{ error?: string }> {
88	  const { user, server } = await ownedServer(serverId);
89	
90	  if (server.status !== "ERROR") {
91	    return { error: "This server isn't in a failed state." };
92	  }
93	  if (await hasInflightJob(serverId)) {
94	    return { error: "Another operation is already in progress on this server." };
95	  }
96	
97	  await db.$transaction([
98	    db.server.update({
99	      where: { id: server.id },
100	      data: { status: "PROVISIONING", provisionError: null },
101	    }),
102	    db.job.create({ data: { type: "PROVISION", serverId } }),
103	  ]);
104	  await db.auditLog.create({
105	    data: { userId: user.id, action: "server.retry_provision", detail: serverId },
106	  });
107	  revalidatePath(`/dashboard/servers/${serverId}`);
108	  return {};
109	}
110	
111	// ---------- 2. Reinstall to a different OS ----------
112	
113	/**
114	 * Switch the server to a different OS image and reinstall. This ERASES all data:
115	 * the worker's REINSTALL handler destroys the VM and re-provisions it from
116	 * `Server.osTemplateId`, so we persist the new template BEFORE enqueuing.
117	 */
118	export async function reinstallToOs(
119	  serverId: string,
120	  osTemplateId: string
121	): Promise<{ error?: string }> {
122	  const { user, server } = await ownedServer(serverId);
123	
124	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
125	    return { error: "Server must be running or stopped to reinstall." };
126	  }
127	
128	  const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
129	  if (!os?.active) return { error: "That operating system isn't available." };
130	  if (os.id === server.osTemplateId) {
131	    return { error: "This server is already running that operating system." };
132	  }
133	  if (server.plan.ramMB < os.minRamMB) {
134	    return { error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM — your plan has ${server.plan.ramMB / 1024} GB.` };
135	  }
136	  if (server.plan.diskGB < os.minDiskGB) {
137	    return { error: `${os.name} needs at least ${os.minDiskGB} GB disk — your plan has ${server.plan.diskGB} GB.` };
138	  }
139	
140	  if (await hasInflightJob(serverId)) {
141	    return { error: "Another operation is already in progress on this server." };
142	  }
143	
144	  // A reinstall destroys and re-clones the VM (same vmid). Its disks — including
145	  // any block-storage volume disk (vm-<vmid>-disk-N) — are purged with it. A
146	  // *detached* volume still keeps its disk under this vmid (Proxmox "unused"), so
147	  // purge wipes it too. Refuse while ANY volume is pinned to this server so the
148	  // customer must delete it (which cleanly destroys just that disk) first.
149	  const pinnedVolumes = await db.volume.count({ where: { serverId } });
150	  if (pinnedVolumes > 0) {
151	    const n = pinnedVolumes === 1 ? "volume" : `${pinnedVolumes} volumes`;
152	    return {
153	      error:
154	        `This server still has ${pinnedVolumes === 1 ? "a" : pinnedVolumes} block-storage ${n}. ` +
155	        `Detaching isn't enough — the disk stays on this server, so a reinstall would erase it too. ` +
156	        `To KEEP the data, attach the ${pinnedVolumes === 1 ? "volume" : "volumes"} to a different server first; ` +
157	        `to discard it, delete the ${pinnedVolumes === 1 ? "volume" : "volumes"} from the Volumes page. Then reinstall.`,
158	    };
159	  }
160	
161	  // Persist the target OS and enqueue the rebuild ATOMICALLY.
162	  //
163	  // The REINSTALL handler re-provisions from `Server.osTemplateId`, so the write
164	  // has to land before the job — but as two separate statements a failure between
165	  // them left the row claiming an operating system the VM is not running, with no
166	  // job to make it true. Every page, every support view and the next reinstall
167	  // would then read that row and believe it. One transaction: either the server
168	  // is recorded as the new image AND a rebuild is queued, or neither happened.
169	  await db.$transaction([
170	    db.server.update({ where: { id: server.id }, data: { osTemplateId: os.id } }),
171	    db.job.create({ data: { type: "REINSTALL", serverId } }),
172	  ]);
173	  await db.auditLog.create({
174	    data: {
175	      userId: user.id,
176	      action: "server.reinstall_os",
177	      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
178	    },
179	  });
180	  revalidatePath(`/dashboard/servers/${serverId}`);
181	  return {};
182	}
183	
184	// ---------- 3. Resize-down ----------
185	
186	/**
187	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
188	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
189	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
190	 * otherwise). A prorated credit for the price difference over the remaining term
191	 * is returned to the wallet.
192	 */
193	export async function resizeServerDown(
194	  serverId: string,
195	  newPlanId: string
196	): Promise<{ error?: string }> {
197	  // Money path: this MOVES money (a prorated credit into the wallet) and it
198	  // permanently gives up capacity the customer paid for. `cancelTransferIn`
199	  // guards its credit the same way; this one did not, so an admin impersonating
200	  // a customer could downgrade their server and cash the remaining term out into
201	  // a balance the customer never asked to convert.
202	  await assertNotImpersonating();
203	  const { user, server } = await ownedServer(serverId);
204	
205	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
206	  if (!newPlan?.active) return { error: "Plan not available." };
207	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
208	  // A GAME server cannot be prorated against its base VPS plan — and THIS is the
209	  // credit path, so this is the dangerous half.
210	  //
211	  // A game tier carries BOTH a `planId` and a `gamePlanId`, and is sold at
212	  // `gamePlan.priceCents`: a FLAT all-in price, typically LOWER than the base plan
213	  // it runs on. `orderGameServer` correctly records `termPromoPercent: 0`, because
214	  // a flat price is not a discounted one. So the credit below is computed from the
215	  // BASE plan's full monthly rate for every remaining month.
216	  //
217	  // lib/proration.ts rests on exactly one invariant — a prorated credit is
218	  // strictly less than the cash actually collected for those months — and this
219	  // breaks it. A $9.99/mo flat tier on a $20.99 base plan pays out $20.99-worth
220	  // per remaining month: real wallet money the customer never paid, self-service,
221	  // repeatable.
222	  //
223	  // Until now it was blocked ONLY by the disk-monotonic guard below, because in a
224	  // catalogue where price and disk both rise there is no cheaper plan with
225	  // equal-or-larger disk. That is a coincidence of the price list, not a
226	  // protection — one cheap high-disk plan opens it. Refusing outright matches how
227	  // `renewalCharge` already treats a game plan: all-in, no add-on lines.
228	  if (server.gamePlanId) {
229	    return {
230	      error:
231	        "Game server plans are fixed bundles — switch tiers from the game server's own settings, or contact support.",
232	    };
233	  }
234	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
235	
236	  // This action is downgrades only — upgrades go through resizeServer().
237	  if (newPlan.priceCents >= server.plan.priceCents) {
238	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
239	  }
240	  // Disk can't shrink destructively; block the move rather than lose data.
241	  // Compares PLAN disks on purpose: any purchased `extraDiskGB` is additive to
242	  // both the old and the new plan and is preserved verbatim across the resize, so
243	  // "new plan disk >= old plan disk" is exactly the condition for "effective disk
244	  // does not shrink". Nothing here ever writes extraDiskGB.
245	  if (newPlan.diskGB < server.plan.diskGB) {
246	    return {
247	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
248	    };
249	  }
250	
251	  if (await hasInflightJob(serverId)) {
252	    return { error: "Another operation is already in progress on this server." };
253	  }
254	
255	  // Credit at the SAME effective rate the upgrade path charges at (term discount
256	  // plus `server.termPromoPercent`, the rate THIS term was actually sold at) over
257	  // the SAME remaining duration — every month left on `expiresAt`, uncapped,
258	  // exactly as lib/resize.ts charges for. Both directions read that one persisted
259	  // scalar off the same row, which is what makes a round trip net to zero no matter
260	  // what dates the two halves happen on. Until 2026-07-26 the rate came from
261	  // `currentPromo(now)` instead, so a customer could upgrade under the 45% Cyber
262	  // Monday basis and downgrade under the 15% Launch Sale basis and keep the spread
263	  // on every remaining month, once per promo cycle, forever.
264	  //
265	  // The old maths credited the raw LIST-price delta, so it refunded more than the
266	  // customer had ever paid (they bought at the term-discounted, promo-reduced
267	  // price). Pricing both directions through lib/proration.ts fixed the RATE, but
268	  // this line then capped the DURATION at one term while the upgrade side did not,
269	  // which broke the round trip the other way: a customer whose stacked "Renew now"
270	  // had pushed `expiresAt` 36 months out on a 12-month term paid $544.32 to
271	  // upgrade Starter -> Max and got only $181.44 back coming straight down, so the
272	  // platform pocketed $362.88 of months they had genuinely paid for. `expiresAt`
273	  // never advances without payment, so all of those months are owed back. The cap
274	  // argument has been removed from `remainingMonths` outright — the two directions
275	  // now cannot express different durations.
276	  let creditCents = 0;
277	  if (!server.isFree && server.expiresAt) {
278	    creditCents = prorateDowngradeCreditCents({
279	      fromMonthlyCents: server.plan.priceCents,
280	      toMonthlyCents: newPlan.priceCents,
281	      termMonths: server.termMonths,
282	      termPromoPercent: server.termPromoPercent,
283	      // Mirror the upgrade charge (lib/resize.ts): credit at the annual rate the server
