637	async function ownedServer(serverId: string) {
638	  const user = await requireUser();
639	  const server = await db.server.findUnique({ where: { id: serverId } });
640	  if (!server) throw new Error("Not found");
641	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
642	  return { user, server };
643	}
