645	export async function serverAction(serverId: string, action: string): Promise<{ error?: string } | void> {
646	  // Returns `{ error }` for anything the CUSTOMER can act on, so ServerControls
647	  // can render it — a `throw` here reaches the browser as Next's redacted generic
648	  // error, discarding the specific, actionable message (e.g. "Delete your data
649	  // volume(s) before reinstalling"). Only genuinely-impossible states still throw.
650	  const { user, server } = await ownedServer(serverId);
651	  const allowed: Record<string, "START" | "STOP" | "REBOOT" | "REINSTALL" | "DELETE"> = {
652	    start: "START",
653	    stop: "STOP",
654	    reboot: "REBOOT",
655	    reinstall: "REINSTALL",
656	    delete: "DELETE",
657	  };
658	  const type = allowed[action];
659	  if (!type) throw new Error("Invalid action"); // not reachable from the UI — a real bug if it happens
660	  if (server.status === "SUSPENDED" && user.role !== "ADMIN") {
661	    return { error: "This server is suspended. Settle the outstanding balance to control it again." };
662	  }
663	
664	  // A reinstall wipes the whole VM, including any block-storage volume the VM
665	  // owns (Proxmox `qm destroy --purge` frees every disk for that vmid).
666	  //
667	  // Count volumes by `serverId` ALONE, never by `status: "ATTACHED"`. Detaching
668	  // deliberately keeps `serverId` set so the volume can be re-attached
669	  // (worker/volumes.ts) — the disk stays owned by this vmid as an `unusedN`
670	  // entry, and PVE's destroy_vm frees unused disks too (include_unused => 1).
671	  // Filtering on ATTACHED therefore missed the worst case: customer fills a
672	  // volume, clicks Detach (the UI promises "Data is preserved."), clicks
673	  // Reinstall — both guards see zero attached volumes, and the purge takes the
674	  // data with it. `reinstallToOs` in actions-server-lifecycle.ts always counted
675	  // by serverId; this path did not. That asymmetry was the bug.
676	  if (type === "REINSTALL") {
677	    const pinnedVolumes = await db.volume.count({ where: { serverId } });
678	    if (pinnedVolumes > 0) {
679	      return {
680	        error:
681	          "Delete your data volume(s) before reinstalling — a reinstall wipes the whole server, and that includes detached volumes still assigned to it. Open Volumes first.",
682	      };
683	    }
684	  }
685	
686	  const pending = await db.job.count({
687	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
688	  });
689	  // Was a silent `return`: the customer clicked Start and nothing happened, ever,
690	  // with no explanation. Tell them why.
691	  if (pending > 0) return { error: "Another operation is already running on this server. Wait for it to finish." };
692	
693	  if (type === "DELETE") {
694	    await db.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
695	  }
696	  await db.job.create({ data: { type, serverId } });
697	  await audit(user.id, `server.${action}`, serverId);
698	  if (type === "DELETE") redirect(user.role === "ADMIN" ? "/admin/servers" : "/dashboard");
699	  revalidatePath(`/dashboard/servers/${serverId}`);
700	}
