"use client";

import { useState, useTransition } from "react";
import { cancelService } from "@/lib/actions-server-lifecycle";

/**
 * Danger-zone control for self-serve cancellation (Finding 2). Offers the two
 * server-side modes — cancel at period end (stop auto-renew, keep to expiry) and
 * immediate termination (destroy now, prorated refund to wallet) — behind an explicit
 * confirm that states the data-retention consequence and the refund figure.
 */
export function CancelService({
  serverId,
  hostname,
  expiresAt,
  autoRenew,
  refundEstimateCents,
}: {
  serverId: string;
  hostname: string;
  /** ISO date; null for a free/no-term server (period-end is not offered then). */
  expiresAt: string | null;
  autoRenew: boolean;
  /** Prorated refund the customer would get on IMMEDIATE termination, in cents. */
  refundEstimateCents: number;
}) {
  const [open, setOpen] = useState(false);
  const [pending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);

  const money = (c: number) => `$${(c / 100).toFixed(2)}`;
  const expiryLabel = expiresAt ? new Date(expiresAt).toISOString().slice(0, 10) : null;

  const run = (mode: "immediate" | "period_end") => {
    if (mode === "immediate") {
      const msg =
        `Immediately terminate ${hostname}? This destroys the server and PERMANENTLY erases all its data — this cannot be undone.` +
        (refundEstimateCents > 0
          ? `\n\n${money(refundEstimateCents)} for the unused part of your term will be credited to your wallet.`
          : "\n\nNo refund applies (nothing left on the paid term).");
      if (!window.confirm(msg)) return;
    }
    setError(null);
    setDone(null);
    startTransition(async () => {
      const res = await cancelService(serverId, mode);
      if (res?.error) setError(res.error);
      else if (res?.message) {
        setDone(res.message);
        setOpen(false);
      }
    });
  };

  if (done) {
    return (
      <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/[0.06] px-3 py-2.5 text-xs text-emerald-200">
        {done}
      </div>
    );
  }

  return (
    <div className="rounded-lg border border-red-500/20 bg-red-500/[0.03] p-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <p className="text-sm font-semibold text-red-200">Cancel this service</p>
          <p className="mt-0.5 text-xs text-slate-400">
            Stop auto-renew and keep it to expiry, or terminate now.
          </p>
        </div>
        {!open && (
          <button className="btn-secondary py-1.5" onClick={() => setOpen(true)} disabled={pending}>
            Cancel service
          </button>
        )}
      </div>

      {open && (
        <div className="mt-4 space-y-3">
          {expiryLabel && (
            <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
              <div className="text-xs text-slate-300">
                <span className="font-medium text-slate-100">Cancel at period end</span>
                <p className="mt-0.5 text-slate-400">
                  {autoRenew
                    ? `Turns off auto-renew. ${hostname} keeps running until ${expiryLabel}, then stops. No charge, no data loss before then.`
                    : `Auto-renew is already off — this server stops on ${expiryLabel}.`}
                </p>
              </div>
              <button
                className="btn-secondary shrink-0 py-1.5"
                onClick={() => run("period_end")}
                disabled={pending || !autoRenew}
              >
                {autoRenew ? "Turn off auto-renew" : "Auto-renew off"}
              </button>
            </div>
          )}

          <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-red-500/20 bg-red-500/[0.04] px-3 py-2.5">
            <div className="text-xs text-slate-300">
              <span className="font-medium text-red-200">Terminate immediately</span>
              <p className="mt-0.5 text-slate-400">
                Destroys the server now and erases all data — this cannot be undone.
                {refundEstimateCents > 0 ? (
                  <>
                    {" "}
                    <span className="text-emerald-300">
                      {money(refundEstimateCents)} is refunded to your wallet
                    </span>{" "}
                    for the unused term.
                  </>
                ) : (
                  " No refund applies."
                )}
              </p>
            </div>
            <button className="btn-danger shrink-0 py-1.5" onClick={() => run("immediate")} disabled={pending}>
              {pending ? "Working…" : "Terminate now"}
            </button>
          </div>

          <button className="text-xs text-slate-500 hover:text-slate-300" onClick={() => setOpen(false)} disabled={pending}>
            Keep my service
          </button>
        </div>
      )}

      {error && <p className="mt-3 text-xs text-red-400">{error}</p>}
    </div>
  );
}

