// ---------------- Billing profile: country + VAT id (Finding 1) ----------------

const profileSchema = z.object({
  // ISO-3166 alpha-2, or empty to clear. Uppercased.
  country: z
    .string()
    .trim()
    .transform((s) => s.toUpperCase())
    .refine((s) => s === "" || /^[A-Z]{2}$/.test(s), "Enter a 2-letter country code (e.g. DE, GB)."),
  vatId: z.string().trim().max(20).transform((s) => s.toUpperCase()),
});

/**
 * Save the customer's billing country + VAT id. These DRIVE the VAT/GST actually
 * charged on their orders and renewals (lib/tax.ts): the country is the destination
 * rate, and a valid EU VAT id in a different member state gets the 0% reverse charge.
 * Left blank => no country on file => tax falls back to the global rate (0 by default),
 * so nothing is charged until the customer supplies a country. Empty strings are
 * stored as NULL so `taxContextForUser` treats them as "unknown".
 */
export async function saveBillingProfile(
  prev: any,
  formData: FormData,
): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();
  const parsed = profileSchema.safeParse({
    country: formData.get("country") ?? "",
    vatId: formData.get("vatId") ?? "",
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid billing details." };
  }
  await db.user.update({
    where: { id: user.id },
    data: {
      billingCountry: parsed.data.country || null,
      vatId: parsed.data.vatId || null,
    },
  });
  revalidatePath("/dashboard/billing");
  return { ok: true };
}

// ---------------- Spend caps + budget alerts (Finding 3) ----------------

const spendSchema = z.object({
  budgetEnabled: z.boolean(),
  budget: z.coerce.number().min(0).max(100000),
  capEnabled: z.boolean(),
  cap: z.coerce.number().min(0).max(100000),
});

/**
 * Save the customer's monthly spend controls: an optional SOFT budget (emails once
 * when this month's service spend crosses it) and an optional HARD cap (refuses new
 * paid orders / manual wallet renewals that would exceed it — enforced in
 * lib/spend-caps.ts assertSpendCap). Both opt-in; disabling clears the stored figure.
 */
export async function saveSpendControls(
  prev: any,
  formData: FormData,
): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();
  const parsed = spendSchema.safeParse({
    budgetEnabled: formData.get("budgetEnabled") === "on",
    budget: formData.get("budget") || 0,
    capEnabled: formData.get("capEnabled") === "on",
    cap: formData.get("cap") || 0,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid spend settings." };
  }
  const { budgetEnabled, budget, capEnabled, cap } = parsed.data;
  const budgetCents = Math.round(budget * 100);
  const capCents = Math.round(cap * 100);

  if (budgetEnabled && budgetCents <= 0) {
    return { error: "Enter a monthly budget amount above $0, or turn the budget alert off." };
  }
  if (capEnabled && capCents <= 0) {
    return { error: "Enter a spend cap above $0, or turn the hard cap off." };
  }

  await db.user.update({
    where: { id: user.id },
    data: {
      budgetAlertEnabled: budgetEnabled,
      monthlyBudgetCents: budgetEnabled ? budgetCents : null,
      // Re-arm the once-per-month alert whenever settings change, so raising the
      // budget can fire again this month if the new figure is already crossed.
      budgetAlertedPeriod: null,
      spendCapEnabled: capEnabled,
      hardCapCents: capEnabled ? capCents : null,
    },
  });
  revalidatePath("/dashboard/billing");
  return { ok: true };
}

