"use client";

import { useActionState, useState } from "react";
import { saveBillingProfile } from "@/lib/actions-billing-prefs";

/**
 * Billing country + VAT id (Finding 1). These determine the VAT/GST actually charged
 * on orders and renewals: the country is the destination rate, and a valid EU VAT id
 * in a different member state qualifies for the 0% reverse charge. Leaving the country
 * blank means no tax is added.
 */
export function BillingProfile({
  country: initialCountry,
  vatId: initialVatId,
}: {
  country: string | null;
  vatId: string | null;
}) {
  const [state, action, pending] = useActionState(
    saveBillingProfile,
    {} as { ok?: boolean; error?: string },
  );
  const [country, setCountry] = useState(initialCountry ?? "");
  const [vatId, setVatId] = useState(initialVatId ?? "");

  return (
    <form action={action} className="space-y-4">
      <p className="text-sm text-slate-400">
        Your billing country sets the VAT/GST charged on purchases. A valid EU VAT
        number in another member state applies the 0% reverse charge.
      </p>
      <div className="grid gap-3 sm:grid-cols-2">
        <div>
          <label className="label" htmlFor="billing-country">
            Billing country (2-letter code)
          </label>
          <input
            id="billing-country"
            className="input"
            name="country"
            maxLength={2}
            placeholder="e.g. DE"
            value={country}
            onChange={(e) => setCountry(e.target.value.toUpperCase())}
          />
        </div>
        <div>
          <label className="label" htmlFor="billing-vat">
            VAT number (optional)
          </label>
          <input
            id="billing-vat"
            className="input"
            name="vatId"
            placeholder="e.g. DE123456789"
            value={vatId}
            onChange={(e) => setVatId(e.target.value.toUpperCase())}
          />
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save billing details"}
        </button>
        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
        {state?.ok && <span className="text-sm text-emerald-300">Saved.</span>}
      </div>
    </form>
  );
}

"use client";

import { useActionState, useState } from "react";
import { saveSpendControls } from "@/lib/actions-billing-prefs";

/**
 * Monthly spend controls (Finding 3): a soft budget that emails once when this
 * month's service spend crosses it, and a hard cap that blocks new paid orders /
 * manual wallet renewals past it. `spentThisMonthCents` is shown as context.
 */
export function SpendControls({
  budgetEnabled: initBudgetEnabled,
  monthlyBudgetCents,
  capEnabled: initCapEnabled,
  hardCapCents,
  spentThisMonthCents,
}: {
  budgetEnabled: boolean;
  monthlyBudgetCents: number | null;
  capEnabled: boolean;
  hardCapCents: number | null;
  spentThisMonthCents: number;
}) {
  const [state, action, pending] = useActionState(
    saveSpendControls,
    {} as { ok?: boolean; error?: string },
  );
  const [budgetEnabled, setBudgetEnabled] = useState(initBudgetEnabled);
  const [capEnabled, setCapEnabled] = useState(initCapEnabled);
  const toD = (c: number | null, fb: string) => (c != null ? (c / 100).toFixed(2) : fb);
  const [budget, setBudget] = useState(() => toD(monthlyBudgetCents, "50.00"));
  const [cap, setCap] = useState(() => toD(hardCapCents, "100.00"));

  return (
    <form action={action} className="space-y-5">
      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm text-slate-300">
        Spent this month:{" "}
        <span className="font-semibold text-slate-100">
          ${(spentThisMonthCents / 100).toFixed(2)}
        </span>
      </div>

      {/* Soft budget */}
      <div className="space-y-3">
        <label className="flex items-center gap-3 text-sm">
          <input
            type="checkbox"
            name="budgetEnabled"
            checked={budgetEnabled}
            onChange={(e) => setBudgetEnabled(e.target.checked)}
          />
          <span className="font-medium">Email me when I reach a monthly budget</span>
        </label>
        <div className={budgetEnabled ? "" : "pointer-events-none opacity-50"}>
          <label className="label" htmlFor="spend-budget">
            Monthly budget (USD)
          </label>
          <input
            id="spend-budget"
            className="input max-w-[200px]"
            name="budget"
            type="number"
            min={0}
            step="0.01"
            value={budget}
            onChange={(e) => setBudget(e.target.value)}
            disabled={!budgetEnabled}
          />
          <p className="mt-1 text-xs text-slate-500">A heads-up email only — nothing is blocked.</p>
        </div>
      </div>

      {/* Hard cap */}
      <div className="space-y-3 border-t border-white/[0.06] pt-4">
        <label className="flex items-center gap-3 text-sm">
          <input
            type="checkbox"
            name="capEnabled"
            checked={capEnabled}
            onChange={(e) => setCapEnabled(e.target.checked)}
          />
          <span className="font-medium">Hard cap — block new purchases past a monthly limit</span>
        </label>
        <div className={capEnabled ? "" : "pointer-events-none opacity-50"}>
          <label className="label" htmlFor="spend-cap">
            Monthly spend cap (USD)
          </label>
          <input
            id="spend-cap"
            className="input max-w-[200px]"
            name="cap"
            type="number"
            min={0}
            step="0.01"
            value={cap}
            onChange={(e) => setCap(e.target.value)}
            disabled={!capEnabled}
          />
          <p className="mt-1 text-xs text-slate-500">
            New paid orders and manual renewals that would exceed this are refused. Auto-renew of
            existing servers is never blocked, so nothing you already run lapses.
          </p>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save spend controls"}
        </button>
        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
        {state?.ok && <span className="text-sm text-emerald-300">Saved.</span>}
      </div>
    </form>
  );
}

